-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[92156] = { id = 92156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Follows Me", description = "You must listen. An evil creature attached itself to me not long ago. It followed me about, angrily hurling objects, playing tricks, and consuming anything it could.\n\nJust now, it stopped following me. It likes you now, I think.\n\nIf you feed it, it should leave you be for a time. Mark the defeated in the Sparring Grounds with this brand. It should consume them, giving us time to talk more.", completion = "It's still hungry. The meals are never enough.\n\nThat's why I'm so weakened. It was constantly nagging me. You seem strong enough, though.", objectives = "Mark 8 defeated Shadowguard in the Sparring Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92157] = { id = 92157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Activity", description = "While you were gone, we were busy.\n\nMy idea is to force the malevolent entity out into the open--out of its hiding places. Havazza gathered up items that have the entity attached to them. I don't trust her, but if she wants to lift heavy things, at least I don't have to.\n\nBy destroying the scattered things it is possessing, we will flush it out of hiding!", progress = "We'll destroy the hiding places, and draw it out.", completion = "I'm sorry. I let that go on far too long. My curiosity outweighed my common sense.", objectives = "Force the entity to appear by destroying the hiding places.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92158] = { id = 92158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let It In", description = "The entity is definitely attached to you, {name}. It even imitated you. I bet it mimics the body of its main target, changing depending on what it's eating. Now that I've seen it in action, I'm confident I can make a container to hold it.\n\nYou trust me, right?\n\nJust outside of Shadow Rise, there is a clear area on the upper bluffs of Claw's Edge. I want to get it away from these objects, like that chair.\n\nBrand yourself as defeated and wait. It will come. Ambush it when you see an opening. We'll trap it!", progress = "You're not that idiotic ethereal, and you have me to help you. You'll be fine.", completion = "It is tiny, harmless, and trapped.\n\nThere is one last thing to do.", objectives = "Feign death on the hill in Claw's Edge and defeat the entity when it comes for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92159] = { id = 92159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Final Destination", description = "Havazza betrayed us and left you to clean up after her. It could have killed you. She should face the consequences of her actions.\n\nI am sure she is back to duels, revelling in her returned strength at your expense. We should start with the Shenzar Refinery area next to the Sparring Grounds.\n\nChallenge her to a real duel!", progress = "She did not give you mercy. Don't give her any either.", completion = "Well done with Havazza. I hated the idea that she'd get away from this without any consequences.\n\nOn the positive side, I can learn a lot from this entity for future disturbances.", objectives = "Meet with Lanlae near the Shenzar Refinery and defeat Havazza in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92162] = { id = 92162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Refined Potadpalate" }
quests[92163] = { id = 92163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loa of Murlocs", description = "Have you heard of de commotion comin' from Atal'Abasi? De murlocs there are gettin' riled up about somethin'.\n\nIt seems like de murlocs have summoned a loa of their own. And dis loa is rallyin' de murlocs to war.\n\nI saw it myself! Just today, lookin' down from dis cliff. De biggest murloc you've ever seen!\n\nI'm not de only one who've seen it either! But de elders say we have bigger problems. Bah!\n\nDey better not come to me when we get overrun by murlocs!", completion = "What brings you to the Loa of Murlocs, traveler?\n\n<King Mrgl-Mrgl lowers his voice to a whisper.>\n\nHelp me!", objectives = "Investigate the Loa of Murlocs at Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92164] = { id = 92164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murloc Madness", description = "These murlocs have come to me, the Loa of Murlocs, to seek my protection against an evil invader.\n\nThe Deepfin have risen from the abyssal depths of the ocean. They have invaded this land and defiled its grounds!\n\nI charge you, champion, to defend this kingdom and drive the Deepfin back into the sea!\n\n<King Mrgl-Mrgl lowers his voice to a whisper.>\n\nGet rid of the invaders and maybe the natives won't need me to protect them, and I can leave!", completion = "Are you finished?\n\n<King Mrgl-Mrgl clears his throat when he sees one of his \"followers\" eyeing him suspiciously.>\n\nI mean, it is finished. The Deepfin shall trouble us no more!", objectives = "Slay 15 Deepfin murlocs at Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92165] = { id = 92165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Are Food, Not Friends", description = "I have heard your mrgls, my people. Your stomachs grgl in hunger!\n\nThe invaders have cut you off from the food you so desperately need to survive.\n\nI will send my champion to gather fish so you may fill your bellies once more!\n\n<King Mrgl-Mrgl lowers his voice to a whisper.>\n\nOr you can just give me fish if you have some?", progress = "My kingdom is ready for a feast! Are you prepared?", completion = "Witness the power of my champion! Be fed, my people, and hunger no more!", objectives = "Collect 30 Murloc-Skewered Lynxfish or give King Mrgl-Mrgl 30 Lynxfish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92166] = { id = 92166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following Suit", description = "My fellow murlocs! One among you was chosen to be my... my chosen!\n\nShe is destined for greatness and is my assistant... erm, priestess! Yes, priestess of the loa!\n\nYour priestess has gone missing, possibly taken by the treacherous Deepfin.\n\nTo showcase my great power, I will send my champion to find and return her to you.\n\n<King Mrgl-Mrgl lowers his voice to a whisper.>\n\nMy assistant is missing, and I'm stuck here! Find her and tell her I'm on top of the temple!", completion = "You found her! Thank you! Erm, I mean... the Loa of Murlocs grants you favor, champion.", objectives = "Track down the priestess of the Loa of Murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92167] = { id = 92167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Can Be Only One", description = "I've observed the Deepfin kidnapping native murlocs and raising troll corpses as undead thralls. But they don't push further inland--they take them all back to the sea.\n\nI think they're being led by a powerful murloc who remains safely offshore, hiding from view as it accepts its minions' tribute.\n\nWe can draw it out. If you put on this murloc suit and offer tribute, it might fool the leader into showing itself.\n\nIf we eliminate the leader, we might be able to save the native murlocs!", completion = "The leader was a kobyss? What is a kobyss?!\n\nI mean... well done, hero! You have served your loa well!\n\nNow that these murlocs are safe, it is time for us to be going!", objectives = "Don the Spare Murloc Suit and offer tribute at the underwater shrine to draw out and slay the leader of the Deepfin murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92177] = { id = 92177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Hero's Prey", description = "Again, we sin'dorei find our city under assault. And again, it is up to the finer minds among us to come to Silvermoon's aid.\n\nMortal anguish, it seems, is a powerful reflection of the soul. When contained and manipulated, anguish acts as a form of magic that we can wield to protect this great city.\n\nI've located a number of anguish-filled targets across Azeroth.\n\nSelect and hunt one such target, storing their anguish in this crystalline vessel. Then return to me.", completion = "While you collect more anguish, I will experiment with this power's potential.", objectives = "Hunt a Prey target and return the crystalline vessel to Astalor Bloodsworn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92178] = { id = 92178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practical Magic", description = "While you've been out pursuing targets, I've been developing various applications for anguish.\n\nThe power these raw emotions contain is unfathomable. For now, our applications might seem quaint, but given enough time, I'm certain my discoveries will further Silvermoon's aims.\n\nLet me show you. Take the crystalline vessel and meet me below.", completion = "For so many years, I've dedicated my life to these magical pursuits.\n\nThis next chapter will be something to behold.", objectives = "Accompany Astalor into the chambers below and imbue objects with the power of anguish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92179] = { id = 92179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Mending", description = "So far, anguish has been invaluable in bolstering our forces. Our weaponry and golems are all the more hardy and potent thanks to this newfound power.\n\nI've also been developing ways to shape anguish into robust enchantments that can strengthen us elves.\n\nMeet me downstairs. I will show you what I've found.", completion = "Unfortunate side effects are expected when we're on the bleeding edge of magical discoveries.", objectives = "Follow Astalor into his lower chambers and assist in his discoveries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92180] = { id = 92180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Jewels", description = "{name}...\n\nWhile you've been away, I've been refining our work.\n\n<He produces a jeweled ring in the palm of his hand.>\n\nSmall trinkets and jewelry that contain crystallized anguish.\n\nI've discretely gifted these to a few willing Silvermoon citizens. I wish to observe the effect of a controlled concentration of anguish over time.\n\nI've shaped the magic to lend the bearer health and strength. Seek our volunteers out and check up on them.", completion = "Aggression is simply an expression of strength.\n\nSo long as we are the predator, not the prey.", objectives = "Check in with the elves that have accepted Astalor's trinkets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92319] = { id = 92319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor to Axe", description = "Kurdran and I spent twenty years in Outland on the other side of the Dark Portal, after we'd pushed the Horde back with Khadgar, Turalyon, and Alleria.\n\nThere were some good times, but any day I don't wake up in Honor Hold is already a good day.\n\nThat whole time, Kurdran led our scouts with his gryphon, Sky'ree. And on his way out of Honor Hold, he would fly low and fast, dodging everything the orcs threw at him. I think it'd be hilarious if you could go find him some mementos!", progress = "What is it, {name}? You have something for me?", completion = "Why are ye bringing me these old, rusty axes?\n\nThey look like the ones orcs used to throw at me back in Hellfire...\n\nSurprising, how far an orc can throw an axe! We had tae stay on our toes, or lose 'em.\n\nWait, did Danath put ye up to... of course he did.\n\nThe one thing worse than being away from home so long was dealing with Danath's sense of \"humor\" all that time.\n\nNot sure which was more off target--the axes or his jokes!\n\nBut he does hit the mark as a friend...", objectives = "Go to Hellfire Peninsula in Outland and retrieve 10 Rusty Battleaxes. Optionally, collect the Scarred Spear from within the Hellfire Ramparts as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92320] = { id = 92320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Behind Enemy Portals", description = "In our reminiscing of past events, we were reminded of an artifact that we did not recover during our war with the Burning Legion.\n\nThis item is a vessel of great evil, and should not stay in the clutches of the remaining demonic forces.\n\nTo reach this item, we must journey to the Broken Shore where Tehd has a portal he has repurposed for our use. Will you join us on this hunt?", objectives = "Journey to the Broken Shore and recover the artifact of great evil. Optionally, acquire the Corrupted Lantern as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92321] = { id = 92321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frostbitten Tally", description = "Tarenar and I heard stories about the invasion of Icecrown Citadel from all the way out in the Plaguelands.\n\nBut he's got it all wrong!\n\nThe elf thinks there were more Ebon Blade commanders than Argent Crusade in the Ashen Verdict. He's completely daft. Obviously there were more paladins!\n\nWould you go poke around Icecrown Citadel and find me some proof? I'm sick of arguing with him!", progress = "You find anything yet? Just need something to prove to Tarenar that I'm right.", completion = "Och, these tabards are looking worse for wear. I guess it's hard to say who showed up in greater force from some old relics.\n\nAnyway, we're on to arguing which of us slept the least while on the Broken Shore.\n\nLooks like you managed to snag an Ebon Blade banner and are still alive to tell the tale. There is a spot nearby to hang that up in the Arcantina.", objectives = "Find 8 Frostbitten Tabards in Icecrown Citadel. Optionally, acquire the Ebon Banner from Icecrown Citadel as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92322] = { id = 92322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees a Proof of Demise!", description = "Hello, {name}. Do you have a moment?\n\nThere's something important I lost during the assault on the Isle of Thunder: a pocket watch gifted to me by my old friend, Archmage Timear. Yes, that Timear... the one that can foresee the future. He told me this day would come and that you would assist me.\n\nThe watch was taken by the Council of Elders, specifically by High Priestess Mar'li. If you would go to the island and retrieve it from the Throne of Thunder, and we both know you will, I can get you there.", progress = "Was Timear's prognostication correct? Have you retrieved my pocket watch?\n\nOr have you simply returned to enjoy my scintillating company?", completion = "Of course you were successful. Timear's insufferably always correct about these things. And, he has returned to rub my nose in it.\n\nYou have my gratitude.\n\nIt appears you've also found an Ancient Zandalari Scroll. Timear has already foresaw it being displayed in the Arcantina. Take a look around for where to put it.", objectives = "Journey to the Isle of Thunder and enter the Throne of Thunder. Inside, retrieve Lan'dalock's Pocket Watch. Optionally, acquire the Ancient Zandalari Scroll as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92323] = { id = 92323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Fire Once Burned", description = "Hard to believe, isn't it? Horde and Alliance, same room, no stabbing.\n\nI was reminiscing about my days in the Firelands, gathering luciferns. They had such a distinctive smell... somewhere between smoke and something long dead. It's been a while, and I almost miss it.\n\nGrab a few for Zen'tabra and me, will you? She deserves the full experience.", objectives = "Journey to Mount Hyjal and enter the Firelands. Inside, retrieve 8 Luciferns. Optionally, acquire the Evergreen Vine as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92324] = { id = 92324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncrowned's Cold Case", description = "We are lucky the Uncrowned survived, and its archives, thanks to Taoshi. We've been reading them...\n\nHave you heard of the great highborne city Dire Maul? The Uncrowned kept tabs on the dangerous prince, Tortheldrin, but since he died, the case was shelved.\n\nThese notes say there might be objects of interest in the city ruins, with a notable mention of Nostro's Compendium of Dragon Slaying. That book was retrieved some time ago, but few know that several chapters were missing.\n\nLet's reopen the case.", objectives = "Journey to Feralas and collect 8 Lost Pages from Nostro's Compendium. Optionally, acquire the Pylon Fragment from Dire Maul as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92325] = { id = 92325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Heritage", description = "My sister Krenna was once a Conqueror in the Horde's armies. Ruthless. Brutal. Some said a tyrant. But she was different when we were young. Scared, but always kind to me. Warm to those she would let in. Did power change her? \n\nAnd if it changed her into a tyrant, did it change Garrosh Hellscream as well? I know who Krenna was. I do not know who Garrosh was. \n\nTravel to Nagrand and find out.", objectives = "Go to Nagrand and discover who Garrosh was in his youth. Optionally, acquire the Weathered Tome as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92326] = { id = 92326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fragrance of the Dunes", description = "I miss the smell of the desert. It is the fragrance of freedom in a wild land. I would love to refresh that scent memory.\n\nWhile you're there, grab something from the caravans. This place could use some nomad personality.\n\nMaybe hop over to Shatterstone Harbor and get something for the big guy. Maybe an anchor? That would be perfect! Imagine watching him lug that around.", objectives = "Go to Vol'dun and bring back a Pouch of Fragrant Sands. Optionally, acquire the Sandy Tapestry from Vulpera Hideaway and the Heavy Anchor from Shatterstone Harbor as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92327] = { id = 92327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Generational Moment", objectives = "Eitrigg and Darius want you to spar with their children.\n\nOptionally, acquire the Clefthoof Hide from Serpent's Coil in the Blasted Lands and the Dried Roses from Pyrewood Village in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92330] = { id = 92330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valorstones", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92331] = { id = 92331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turbo-Boost: Trade Must Flow", description = "<The Trust is under pressure from the cartels to keep markets open. We seek associates capable of removing certain... obstacles. Cartel So has been authorized to distribute substantial riches if you are successful.\n\nComplete the task, and collect a special reward from Fixer So'kir outside of the Dornogal Treasury. Parties shall remain unbound by any implied oaths arising in the course of trade. Uniform Broker Code standard terms apply.>", completion = "The Trust thanks you for your assistance, {name}. \n\nAs promised, here is your reward. \n\nTo celebrate the success of our new partnership, we are including a small performance bonus. Please return later for more work!", objectives = "Defeat any four bosses within the Manaforge Omega raid on Normal difficulty or higher, or complete any four Mythic Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92332] = { id = 92332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turbo-Boost: Infinite Growth", description = "<The Trust always has more work to be done if we are to ensure continued growth for our trade. Once again, Cartel So has been authorized to distribute substantial riches if you are successful.\n\nComplete the task, and collect a special reward from Fixer So'kir outside of the Dornogal Treasury. Parties shall remain unbound by any implied oaths arising in the course of trade. Uniform Broker Code standard terms apply.>", progress = "Again, you prove yourself a friend of the cartels! Well done.", completion = "The Trust thanks you for your assistance, {name}. \n\nAs promised, here is your reward.", objectives = "Defeat any four bosses within the Manaforge Omega raid on Normal difficulty or higher, or complete any four Mythic Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92364] = { id = 92364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sun Support" }
quests[92365] = { id = 92365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creating Defenses", description = "Deploying defenses is crucial to safeguarding operation of the Singularity Anchor. I need to ensure you fully understand the process.\n\nFirst, collect the Stormarion cores I have in storage. Then, activate the defensive positions, and finally, choose and deploy one defense at each position.\n\nWhen you have completed that I can entrust you with further Stormarion cores to use as you see fit.", progress = "Have you deployed the defenses?", completion = "You've done well, I feel safe entrusting you with these additional Stormarion Cores, use them wisely!", objectives = "Follow the steps and deploy two defenses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92386] = { id = 92386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Voidlight Marl", objectives = "Thank you for your assistance. Please accept these as thanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92387] = { id = 92387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cluster of Voidlight Marl" }
quests[92390] = { id = 92390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risk for Research", description = "There is some peculiar activity in Shadow Rise to the northeast. Supposedly it is cursed! The Shadowguard usually have a heavy presence there, but I have word that they are abandoning the site.\n\nI want to find out the truth of why they'd leave. Would you accompany me?", completion = "<Lanlae shakes off the pain of the assault and forces a smile to her face.>\n\nHow thrilling! That was a proper good scare.", objectives = "Meet Lanlae Noxa in Shadow Rise to look around the Shadowguard facility.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92396] = { id = 92396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling in the Cavalry", description = "The wards on the runestones weaken by the hour. Without fresh arcane-charged crystals, the Lightbloom will gain ground.\n\nI know this is not your burden to bear as you have much more to handle, but if you could see these supplies delivered, it would mean more than I can say.\n\nWill you lend your strength to this task, for the sake of all who call this place home?", progress = "What to do...", completion = "Ah, you're the one who brought the supplies. My thanks! The wards are stable now. However, there's another task here that could use your attention.", objectives = "Deliver charged crystals to Runestones across Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92397] = { id = 92397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dawnstar Defense", description = "The nearby runestone has gone dark, and the Lightbloom is on its way. I can't hold this ground alone. Help me set the weapons, line up the potions, and get our supplies in order.\n\nWe'll meet that growth with discipline and precision and send it back in pieces.", progress = "Have you finished setting up?", completion = "Good work. Now for the hard part.", objectives = "Build up defenses before the impending Lightbloom attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92398] = { id = 92398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Then They Came", description = "Brace yourself--the time is upon us!\n\nHold the line and keep them from reaching the runestone at all costs. I'll focus on restoring its power, but I need you to protect me and everyone here.\n\nAre you ready?", completion = "The runestone hums with power again thanks to you. You have my appreciation.", objectives = "Defend Dawnstar Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92402] = { id = 92402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magical Touch", description = "Oh hey, just the person I was looking for!\n\nSome of your neighbors are looking to get into enchanting. They aren't quite ready for prime time yet, but I have an idea to get them started.\n\nIt looks like there's an area in your neighborhood that has slight magical energy. Can you take this locator and find some crystals for them?\n\nThey only need to be slightly magical. We don't want them to cause an accident!", progress = "Did you get a chance to pick up those crystals yet?", completion = "Oh nice! Yeah this is perfect.\n\nThank you so much!", objectives = "Collect 15 Slightly Magical Crystals in your neighborhood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92405] = { id = 92405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Arator", description = "Greetings, champion. I have an urgent message for you from Arator. He asks that you join him and his aunt Vereesa on Oztan Isle, off the coast to the west.", completion = "My aunt has been having terrible visions and they are getting worse.", objectives = "Seek out Arator and Vereesa Windrunner on Oztan Isle off the Isle of Dorn coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92407] = { id = 92407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidey-Hole", description = "When Xal'atath departed she left behind a large number of anomalies, small pocket dimensions where enemies can hide. As Romuul calls them, \"Hidey-Holes\".\n\nThe Artificer has rigged up a device that should do the job.\n\nWe need to close these Hidey-Holes and flush out any enemies lurking inside.", progress = "Have you removed the anomalies?", completion = "Excellent work, I'm sure we'll discover more anomalies hiding about, but with your help we've eliminated any immediate threats.", objectives = "Use the Anomaly Inverter to collapse 5 Hidey-Holes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92408] = { id = 92408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Material Gains", description = "How on Azeroth one of these encroaching paladins managed to come by such an exquisite example of Thalassian tailoring is beyond me. But it would be negligent of me to turn down this opportunity.\n\nThe materials we need are far more bespoke than I keep in my shop, however. We'll need to source our manasilk directly. Fortunately, it isn't far--just outside the city gates.\n\nAnd at least there we'll be safe from these dabblers.", completion = "You will find no higher quality of manasilk in all of Eversong, let alone the world.", objectives = "Meet Solwin Brightstitch at the manasilk mill in the North Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92410] = { id = 92410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Magisters", description = "The Magisters owe you a great debt.\n\nSpeak with me at Saltheril's Haven. You will be duly compensated for your aid.", sourceObjective = "Speak with Appentice Diell in Saltheril's Haven.", sourceObjectiveStatus = "unverified-source-field" }
quests[92411] = { id = 92411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Blood Knights", description = "The Blood Knights owe you a great debt.\n\nSpeak with me at Saltheril's Haven. You will be duly compensated for your aid.", sourceObjective = "Speak with Armorer Goldcrest in Saltheril's Haven.", sourceObjectiveStatus = "unverified-source-field" }
quests[92412] = { id = 92412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Farstriders", description = "The Farstriders owe you a great debt.\n\nSpeak with me at Saltheril's Haven. You will be duly compensated for your aid.", sourceObjective = "Speak with Ranger Allorn in Saltheril's Haven.", sourceObjectiveStatus = "unverified-source-field" }
quests[92413] = { id = 92413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Shades of the Row", description = "The Row owes you a great debt.\n\nSpeak with me at Saltheril's Haven. You will be duly compensated for your aid.", sourceObjective = "Speak with Neriv in Saltheril's Haven.", sourceObjectiveStatus = "unverified-source-field" }
quests[92417] = { id = 92417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farm to Table", description = "Hey, it's {name}!\n\nI'm in a bit of a pickle here. I'm making food for everyone, but underestimated how many people would turn up!\n\nI can whip up a quick stew and the local farmers said I could use their produce, but the other dishes are at a vital point, I can't leave them unattended!\n\nCould you gather some ripe ingredients, and bring them back?", progress = "Please hurry back with the ingredients!", completion = "Thank you so much!\n\nI can get the rest of this food ready now, you really are the best!", objectives = "Collect enough ingredients to form a good stew and return to Yolan Hidor within the neighborhood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92418] = { id = 92418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abundance" }
quests[92429] = { id = 92429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alternative Skinning", description = "Hey there!\n\nI'm working on a new method for making leather, but without harming animals.\n\nI just need small samples, fur, saliva, that sort of thing. Nothing invasive.\n\nI have this handy device that should help out!", progress = "Thanks for your help on this. I'm really excited to see if I can make this work.", completion = "Let's see what we can do with it!", objectives = "Use the Biological Vacuum to collect samples from large animals around the neighborhood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92430] = { id = 92430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Embracing the Infinite Chaos", sourceObjective = "Speak with Eternus at the Infinite Bazaar near Dalaran.", completion = "Excellent timing, {name}. Now the research can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[92437] = { id = 92437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nStone laid by lost hands.\nBridging the mountain runoff.\nLook where lilies listen.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92439] = { id = 92439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Felrunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of fighting the Legion with their own power, so focus on using demonic fel energy to slay your foes.\n\nAnd remember, this is for the greater good.", progress = "Remember to pace yourself, the journey is just as important as the destination.", completion = "Impressive. I can sense your power. This is a most critical addition to our research.", objectives = "Kill 100 enemies while Twisted Crusade is your active artifact ability.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92440] = { id = 92440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Stormrunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the storm, so focus on fighting opponents by turning the tides quite literally.\n\nAnd remember, this is for the greater good.", progress = "Remember to pace yourself, the journey is just as important as the destination.", completion = "Impressive. I can sense your power. This is a most critical addition to our research.", objectives = "Kill 100 enemies while Tempest Wrath is your active artifact ability.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92441] = { id = 92441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Magerunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the arcane, so focus on fighting opponents with powerful magic.\n\nAnd remember, this is for the greater good.", completion = "Impressive. I can sense your power. This is a most critical addition to our research.", objectives = "Kill 100 enemies while Naran's Everdisc is your active artifact ability.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92442] = { id = 92442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinite Research: Combat Studies, Lightrunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the Light, so focus on wielding holy justice to smite your enemies.\n\nAnd remember, this is for the greater good.", progress = "Remember to pace yourself, the journey is just as important as the destination.", completion = "Impressive. I can sense your power. This is a most critical addition to our research.", objectives = "Kill 100 enemies while Vindicator's Judgment is your active artifact ability.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92443] = { id = 92443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reverse Herb Farming", description = "Hey there, I was collecting herbs around your neighborhood, and I kind of zoned out, and lost track of time. It's so pretty here!\n\nI think I may have picked too many herbs. I have an enchanted watering can that should help new ones grow back in, if you have the time to help them grow back?", progress = "I feel really bad, I'm so sorry.", completion = "Thanks for helping me out, {name}. \n\nI just had a really good route and got into the zone!", objectives = "Water 15 plants in your neighborhood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92445] = { id = 92445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smelting for Two", description = "People keep coming up to me and asking me about mining, I'm not a miner, I'm a smelter!\n\nI'm looking to teach some people about smelting, but I've been struggling with getting a crowd.\n\nCould you help me out while I talk you through smelting?", progress = "Smelting is so much fun!", completion = "Wooo! Smelting!", objectives = "Assist Jaren with smelting in the neighborhood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92448] = { id = 92448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Dust Dances", description = "You find a faintly glowing powder in your hands after catching the moth. It is fine, dry, and oddly luminous. \nIt doesn't hum or shift, but it catches the light in a way that feels deliberate.\n\nYou recall Mothkeeper Wew'tam is known to have a particular interest in the moths that reside in Harandar.\n\nPerhaps this dust would be of interest.", completion = "Ohhh... this Dust sparkles like a dream!\n\nIf you find more, bring it to me! I've treasures rare and wonderful to trade for in exchange!", objectives = "Speak to Mothkeeper Wew'tam in the Den.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92450] = { id = 92450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Up is Hard", description = "Oh, hi! You're new. I'm Ani. Dis is Jynx.\n\nHave you been to de waterfall yet? All de kids dare each other to jump off, but I'm too scared.\n\nDo you want to see it?", completion = "See? It's a long way down.", objectives = "Head to the waterfall with Ani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92451] = { id = 92451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Think I Can", description = "Yeah, it's pretty far down.\n\nBut if I don't jump, dey'll make fun of me. Maybe if you cheer me on, I can do it?", progress = "I don't want dem to make fun of me anymore. I-I can do dis. I think...", completion = "<Ani's bag of treasured trinkets sits empty on the marsh bank, already sinking into the soft mud.>", objectives = "Help Ani conquer her fear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92452] = { id = 92452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not According to Plan", description = "<Ani's trinket bag sits in the soft mud of the river bank, but her trinkets are nowhere to be found.\n\nIf you're lucky, you may be able to follow her trail.>", completion = "I wasn't sure how much longer I'd last out here. I was runnin' out of rocks!", objectives = "Follow the trail of Ani's belongings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92453] = { id = 92453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fearless", description = "Those lizards were waitin' at de bottom and dragged me off!\n\nDid you find my toys and stuff? I tried droppin' dem so someone could find me. I can't believe dat worked!\n\nI think you scared dem off. It should be safe enough for Jynx to help me out of here.", progress = "Jumpin' off dat waterfall isn't so scary anymore.", completion = "Hey, {name}! I jumped off de waterfall and I killed a big lizard!\n\nI know you helped.\n\nJynx helped too.\n\nThanks!", objectives = "Meet Ani back at Amani'Zar Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92492] = { id = 92492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honorin' de Sacrifice", description = "It's de hash'ura again. You willin' to help me, or does Zul'jarra got you on a short leash?\n\nNo? Then I got a job for you. One of my guards, Idago, was killed in de massacre at Revantusk Sedge. I wish to honor him with funeral rites. We Revantusk burn de bodies of our dead. But we don't have Idago's body.\n\nSo, I'm goin' back to de sedge to retrieve somethin' of his. We'll burn dat instead.\n\nMy honor guard Pel'na will not go and says it is too dangerous, but you'll keep me safe, won'tcha?", completion = "Stay down, {name}! Don't give away my hidin' spot.", objectives = "Meet Lilaju at Revantusk Sedge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92493] = { id = 92493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Remains of Idago", description = "Idago was my most trusted guard. He was a mentor to me for as long as I remember. I never thought dat he would be taken from me so soon--and then de Twilight's Blade attacked us without warnin'.\n\nIdago is de one that saved me from de village. He left his spear and his banner behind. I also left a note he gave me in case he...\n\nBring me those items. With dem, we can honor his strength and his loyalty--and send his spirit on.", progress = "Revantusk Sedge is swarmin' with these foul mages. You're doin' de loa's work.", completion = "Idago was taken into de crypt! They are sayin' de big boss Mish'mosh has somethin' nasty in store for him.", objectives = "Find Idago's Warspear, Banner, and Letter in Revantusk Sedge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92495] = { id = 92495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disruptin' de Blade", description = "Look at what these cultists did to Revantusk Sedge!\n\nDis was once a place of peace... dis was our home. An' dey are desecrating it.\n\nI know we're here to retrieve Idago's things, but I won't be bothered if you take up arms against de Twilight's Blade.\n\nPut dem in de ground. Show dem de ferocity of de bear.", progress = "One day, we're gonna march on these invaders an' take our sedge back!", completion = "By Nalorakk's maw, you put a dent in their forces.", objectives = "Slay 7 Twilight's Blade Enforcers, 7 Shadowmages, and 3 Baleful Darkspawn at Revantusk Sedge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92496] = { id = 92496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spears Against de Shadow", description = "Idago's still alive, {name}!\n\nI saw him dragged up into de crypt, bound in magic runes. \n\nDe cultists say dey are takin' him to some Deathchanter Mish'mosh. Dis cultist must be behind the death and destruction brought to our sedge.\n\nFor the honor of the people we lost, root this snake out of our home!", completion = "You've done a great honor for our tribe by defendin' our lands against de Twilight's Blade.\n\nBut Idago is not happy that I came back.", objectives = "Slay Deathchanter Mish'mosh in the crypt at Revantusk Sedge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92497] = { id = 92497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simply Magical", description = "Who... Who are you? Who sent you? Lilaju?\n\nDe cultists massacred our village. I stayed behind to make sure everyone got out.\n\nBut de cultists captured me and now dey say dey got somethin' extra special for Idago. I'd rather not find out what.\n\nDis magic holdin' me here is amateur work. De spells to release de bindings are sure to be in de magical tomes de cultists brought here.\n\nFind de tomes and rip some pages out. Then we can piece together de right words to release me.", progress = "Appreciate ya, {name}. For freeing me and for keeping an eye on dis one here.", completion = "De girl's foolishness aside, I owe you my life.", objectives = "Rip the pages from the Tome of Binding and the Tome of Pain and recite their words to free Idago.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92499] = { id = 92499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wisest Leaders Follow", description = "Idago reminded me dat my first obligation is to my tribe. I missed him dearly, but it was not right for me to put my own life--or yours--at risk to find him.\n\nPel'na tried to tell me this. I would not listen.\n\nI must be a model for my people. I will allow de bear loa to guide my direction. Sometimes we must sacrifice de things we hold dear.\n\nNalorakk grant me strength and resilience.", completion = "I stand by my decision, but I should apologize both to Pel'na and Idago.\n\nDey have wisdom to offer me... and in return, I will guide them through these troubling times.", objectives = "Return to Lilaju at Torntusk Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92505] = { id = 92505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truth of the Past", description = "Thanks for freeing me from those ethereal cages in the Ethereum Overcroft. The Void is powerful here in ways we're only beginning to understand, and that danger brings new opportunities.\n\nIf you remember, my quest to combine the power of the Void with the strength of the Illidari has not changed.\n\nBacking Adarus was a mistake, but a necessary one to progress. And now I've found a willing teacher in Allari. I ask for your help again, {name}. Help me find the strength to protect my people.", completion = "I haven't set foot on Argus in years. A dead world, populated by a broken people and their memories.", objectives = "Travel to Argus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92506] = { id = 92506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Price", description = "Argus.\n\nOriginally the homeworld of the Eredar, now the stronghold for the Burning Legion. Years ago, Illidan used the Seal of Argus to open the way here. And he was met by one of the naaru who delivered a dire message.\n\nTo understand the Illidari's connection to the Void, you must see what Illidan saw when he arrived. Hostile spirits in the area should provide the necessary power for our needs.\n\nDefeat them to release their essence, and with their sacrifice we will peer into the past.", progress = "The energy from these spirits will serve as a conduit for us to access the past.", completion = "Yes, that looks like enough. We're nearly prepared, {name}.", objectives = "Free spirits and collect their energy in Kil'jaeden's Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92507] = { id = 92507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A More Potent Foe", description = "We have what we need.\n\nPrepare yourself to see Illidan's confrontation with the naaru so many years ago.", completion = "I've only ever wanted to protect my people. Just like how demon hunters protect Azeroth.", objectives = "Watch the scene on the platform.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92508] = { id = 92508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Sacrifice", description = "The tattoos that mark our flesh are more than just ink. They're a promise inscribed across our flesh.\n\nThe promise that we will hold back the dark and the infernal with our very bodies. That our lifeblood is a currency used to purchase Azeroth's future.\n\nSurprised? We are not simply rage and defiance manifest, although we are also that.\n\nHelp Leona collect the vitae of the void creatures at Nexus-Point Antius. We'll use it to inscribe her tattoos, affirming the vow she makes to protect her people.", completion = "Yes, this captured void energy will do nicely.", objectives = "Harvest vitae from the void creatures of Nexus-Point Antius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92509] = { id = 92509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Cruel Implement", description = "Voidstorm is a world of apex creatures. One in particular, the ultradon, stands above others in its strength and ferocity.\n\nBut make no mistake, {name}. We demon hunters are the true apex predators wherever we go, because we are willing to go to any length in order to dominate. I see no better creature to harvest an implement in which to inscribe Leona's tattoos.\n\nHead to Nexus-Point Antius with Leona. Defeat as many ultradons as it takes to find the perfect implement.", progress = "Have you found the talon yet, {name}? Without it, we cannot start Leona's ritual.", completion = "There is no question now, {name}. Demon hunters are the apex predators on this planet.", objectives = "Harvest a Talon from the Ultradons at Nexus-Point Antius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92510] = { id = 92510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Infusion", description = "The branding ritual we're about to perform is adapted from what demon hunters go through on the Fel Hammer. But given Leona's unique nature and the experimental substitution of Void energy for fel, there's considerable risk here. Even more so than usual.\n\nLeona will be vulnerable during this process, as will I. We've found a secluded area to perform it, but we'll need your protection once we start.", completion = "I believe we have some equipment that can be repurposed to help Leona return to us.", objectives = "Enact the branding ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92511] = { id = 92511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Event Horizon", description = "It may not surprise you to know that the stabilization of portal entry points is something I'm quite familiar with.\n\nIf Leona lives, and I believe she does, she'll need beacons to help triangulate her exit point. Take these beacons, set them up where I've marked on your map, and return here.\n\nIf Leona is alive, she should be able to use these beacons to identify and stabilize her exit.\n\nIf she isn't--\n\n<Umbric pushes the thought away.>\n\nLet's focus on the task at hand for now.", completion = "That voice. A domanaar. I think I can sense it now. He'll come for us if we don't find him first.", objectives = "Place the beacons to help Leona find her way back.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92512] = { id = 92512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devourer", description = "I'm not sure where I was when I stepped through that portal, {name}. Somewhere in between, Void energy surrounding and suffusing me.\n\nWithout Umbric, I wouldn't have made it back. I feel different now, but I don't think this is over until we confront that domanaar.\n\nWill you meet us at the Voidspire?", progress = "I await with eagerness and a bit of trepidation for Leona.", completion = "Leona's determination and willingness to fight for our people is admirable.\n\nShe fought hard and sacrificed much to reach this point, and her life will be forever marked by those trials. But the ren'dorei are stronger for it.\n\nWho would've thought that such a dark and predatory world would be the catalyst for a brighter future?", objectives = "Help Leona confront Ravenor at the Voidspire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92520] = { id = 92520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wake of the Darkwell", description = "The Sunwell--no... the Darkwell is overrun. \n\nVoid-spawned creatures swarm the regions where our greatest champions of the Light held their ground to the very last.\n\nChampion, can you survey Quel'Danas? Find any survivors? If you tag them with these tokens, our mages here will be able to teleport the individuals back. We must try to save as many as we can.", objectives = "Search for Survivors on the Isle of Quel'Danas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92523] = { id = 92523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[92524] = { id = 92524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[92531] = { id = 92531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Medicine Loa's Shrine", description = "Everyone has their own path toward understanding, even Akutu--though he has yet to set foot on it, unfortunately.\n\nMy shrine was once a place of discovery and understanding for the Amani. Please take word to them that I welcome their return.\n\nThe ghosts will calm in time.", completion = "Dat is quite de ghost story!\n\nI am sad dat I will not talk to Sij'ta again, and dat Kulzi has lost his loa speaker, but I am glad Sij'ta has found peace at last.\n\nI will go and speak to Kulzi. I hope there are no hard feelings there.", objectives = "Return to Elder Doru with news of Kulzi's return.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92546] = { id = 92546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Predators" }
quests[92547] = { id = 92547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of the Hara'ti" }
quests[92554] = { id = 92554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Addition of Anguish", description = "?" }
quests[92563] = { id = 92563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awoken by Accessory", description = "<As you equip the jewelry, you feel it surge with power, flowing through you and into your artifact weapon.\n\nThe jewelry has unlocked hidden potential of your artifact weapon, enabling and empowering one of its traits.\n\nMoratari will want to record this data.>", completion = "Fascinating, it seems as though the magic of your new accessory is capable of awakening otherwise inaccessible powers of your artifact weapon, or even enhancing them beyond their limits!\n\nI wonder if all jewelry has this same connection to your artifact weapon. Please do keep me informed of any more anomalies.", objectives = "Speak with Moratari at the Infinite Bazaar near Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92566] = { id = 92566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armies of Darkness" }
quests[92568] = { id = 92568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drustvar Candy Exchange" }
quests[92570] = { id = 92570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwood Candy Exchange" }
quests[92571] = { id = 92571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armies of Darkness" }
quests[92572] = { id = 92572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furniture Favor", description = "Greetings! I see you are eyeing our fine furniture.\n\nMy siblings and I were sent on a mission to find only the finest Decor in the land.\n\nDecor is more than furniture, you see. Crafting a truly great decoration requires attention to so many different details.\n\nCome, friend, let us go on that journey together! Starting today. Today, we find a crate. Not just a normal crate, one that is fantastic. A great crate.\n\nI hear they may sell them nearby, actually...", progress = "How is your day going? Is it fantastic?", completion = "Oh my, the crate you describe does indeed seem quite great. The joy of placing them will know no bounds.\n\nThank you for finding this! For your time, might I present you with this rare piece from our collection.\n\nIt is no ordinary barrel, to be sure! I hope that you enjoy it thoroughly.", objectives = "Purchase a Storage Crate in Dornogal, Stormwind, or Orgimmar, and return to a Pawdo sibling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92576] = { id = 92576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dominating The Domanaar" }
quests[92577] = { id = 92577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreamy Inspiration", description = "A crate is nothing more than a box in the dark without lighting. \n\nToday, we go in search of the tiny suns that light our spaces. \n\nNot just any light will suffice. As you can clearly see from my chandelier, we have many lights of varying quality already.\n\nWe seek a unique shape, a unique feel. \n\nThe crafters of Bel'ameth in the Dragon Isles are well-known for their dream-inspired designs. Travel through the Dragon Isles and you will find them at the far end of the plains.", progress = "You never really know a cabinet until you've checked the hinges.", completion = "Your new magical light is quite astonishing! The accents of the finely-curved metal... \n\nIn terms of metal balls, I have seen few of its quality. I would place it on a desk or end table. I can see it now! \n\nThough I will have no place to put my scrolls, I must provide something in return. Take my bookshelf, it has served me well.", objectives = "Purchase a Filigree Moon Lamp in Bel'ameth in the Dragon Isles, then return to a Pawdo sibling in Dornogal, Stormwind, or Orgimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92578] = { id = 92578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Decor", description = "The chandelier I showed you? You must think it so fancy. \n\nBut here I am without the matching sconces!\n\nWhat room lighting can I create without matching sconces? It will be woefully incomplete!\n\nHead over to the Dragon Isles and see if you can find one from the vendors of Valdrakken.", completion = "Ah! You have located the sconces, then. I shall head over and purchase some myself at once, thank you! \n\nJust as soon as you are not looking.", objectives = "Purchase a Draconic Sconce in Valdrakken in the Dragon Isles, then return to Pawdo in Dornogal, Stormwind, or Orgimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92580] = { id = 92580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare A Chair", description = "We cannot enjoy our Decor designs without a place to enjoy them from. \n\nBehold, the chair.\n\nWhat better way to enjoy Decor than on Decor itself?\n\nI cannot imagine something more appropriate.\n\nFind me a chair to match this coil. The gearcrafters of Mechagon know the style.", completion = "Ah, the chair that you found, it is quite appropriate indeed.\n\nFor you, this coil. \n\nI hope that you do not shock yourself! Sometimes we must sacrifice for art.", objectives = "Purchase a Bolt Chair in Rustbolt in Mechagon, then return to Pawdo in Dornogal, Stormwind, or Orgimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92581] = { id = 92581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Light", description = "I have sat in the chair and looked at the lights, and yet I am still not satisfied. \n\nThe Decor still does not strike the dramatic tone that we require.\n\nI must trouble you for another source of the light's rays. \n\nTravel to Suramar and speak to the crafters there. They are masters of the art of soft lighting.", completion = "You have found the requested Decor once more! \n\nYou are quite talented at this. I hope that you continue your adventure into the world of Decor, for there is no limit to it beyond your creativity. \n\nYou may take the table in front of me, for I have no more need of it. Perhaps we shall meet again!\n\nUntil then, farewell!", objectives = "Purchase a Nightborne Lantern in Suramar in the Broken Isles, then return to Pawdo in Dornogal, Stormwind, or Orgimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92600] = { id = 92600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracked Keystone", description = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive.\n\nPerhaps performing a suitably impressive task will stabilize the stone's magic once more?", objectives = "Complete any dungeon on Mythic 2 or higher difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92603] = { id = 92603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O Lonely Star", description = "<The void elf writhes in a fitful sleep, tormented by the nearby shade.\n\nPerhaps you should try to wake him.>", completion = "Thank you for accompanying me. I didn't really have anyone else to ask.\n\nThe other ren'dorei... The Void changes many things, but I feel just as out of place in Telogrus as I did in Silvermoon.", objectives = "Learn more about the shade tormenting Orin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92604] = { id = 92604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak in Blood", description = "After my failed creation, I sought wisdom from the Void, and it told me of this place.\n\nThere was a voice--strange, yet familiar. It promised a tool for shaping Void and shadow--something that would free me from my failure, but the Void gives nothing freely. We must command it, and violence is this land's mother tongue.\n\nSlay the beasts here and bring me their ichor. We'll use it to write our demands.", progress = "Do you have it? The shade won't be silent. It wasn't meant to exist like this.", completion = "I hope it wasn't too much trouble. This sort of work was always beyond me. I never could grasp the more violent Void arts.", objectives = "Gather 50 Viscous Ichor from creatures in the Fangfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92605] = { id = 92605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honest as Bone", description = "If ichor is to be the carrier for our message, bone shall be its pigment. This is a place of scavengers, with bones stolen from across this land: old, new, all carrying the echoes of violence that brought their ends.\n\nBring me bone splinters and I will powder them for our ink.\n\nPlease hurry. This shade is a wrong thing, and I must put it right.", progress = "These scavengers must have brought bones from all over Voidstorm.", completion = "Perfect. Give me a moment to powder this and we'll soon have the pigment we require.", objectives = "Gather 8 Bone Splinters from the Fangfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92606] = { id = 92606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Up Your Gift", description = "This place--this wound--is what the voice from the Void told me I'd find. There's something waiting inside... something to put an end to this broken creation.\n\n<Orin winces and glares at the shade.>\n\nYou can't hear it? It howls. Sometimes in rage. Other times it sounds so lonely that it breaks my heart.\n\nIgnore it. With the proper runes written in ichor and bone, I believe we can open this rift wider. Then you can seize what lies within.", progress = "The voice spoke true. There was something waiting here.", completion = "Remarkable. This chisel is not made to carve stone or metal, but the Void itself. It can free me from this shade.", objectives = "Help Orin open the rift and uncover what lies within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92607] = { id = 92607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Carve New Shapes", description = "This is what the voice from the Void promised me: the means to divest myself of this shade.\n\nYou'll have to wield it. Don't worry--it won't harm me. It will separate me from the shade. Then it should simply fade away, no more than an unmoored shadow.\n\nGo on. I'm ready.", completion = "The shade wasn't trying to torment me--it was in agony. I'd made it in the depths of my loneliness, and it reflected that: bound to me, unable to exist alone, trying to provide comfort it couldn't while stuck as my shadow.\n\nI'd looked outwards to deal with my loneliness. Finding the Void, becoming ren'dorei, following the others here... I thought if I just found the right place, I wouldn't feel this way. \n\nBut I was wrong. It was always inside me. I couldn't cast it out, only embrace it.", objectives = "Separate Orin from his shade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92608] = { id = 92608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landscape Photography", description = "I'm having just the best time in your lovely village, it's so quaint!\n\nI'm feeling inspired. I would like to paint a landscape picture to commemorate the occasion. But you know the area better than I.\n\nCould you provide me with some pictures of the landscape I can use for inspiration? You can use my camera. It's top of the line, of course.\n\nI'm sure the perfect spots will just beam at you.", progress = "This place is such a delight, so laid back and rustic.", completion = "Oh my, these photos are just exquisite!", objectives = "Take enough photos of your neighborhood to inspire Corlen Hordralin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92616] = { id = 92616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushrooming Courage", completion = "Sporegliders very scary. Could still sneak up and attack. Hurt Brakko's cap.\n\nBut {name} made Brakko practice. Now can fight sporegliders, even when scared.\n\nScared does not mean Brakko have to run.\n\nReady now to fight for the Fungal Fellosh.\n\nEven if we fight sporegliders, Brakko will not run.", objectives = "Help Brakko face his fear of sporegliders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92617] = { id = 92617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushrooming Resilience", progress = "Ziny will try to heal {name}.", completion = "{name} did not die! Ziny healed {name}.\n\nWould have been Ziny's fault if {name} died, but {name} lived. Because Ziny healed, even though enemies were scary.\n\nSo scary.\n\nHooray! {name} welcome. For help.\n\nAnd {name} is thanked. For showing can do together.\n\nCan be the Fungal Fellowship now. Will win Grudge Pit, for sure.", objectives = "Face 4 scary enemies with Ziny.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92618] = { id = 92618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushrooming Confidence", description = "Tuktuk's poison is not good enough. Tuktuk had to run, before we lose.\n\nSorry if you lose! Tuktuk did not lose. Tuktuk quit. Quit is safe from lose.\n\nGrudge Pit very, rrr... is so intense. Tuktuk cannot handle. Tuktuk will stay out where is safe.\n\nTuktuk will find place to relax. Away from Grudge Pit.\n\nTuktuk cannot lose if stay far away.", completion = "Tuktuk could lose! Be beaten.\n\nVery scary. But {name} would still be friend. Brakko would still be friend. Ziny would still be friend. \n\nWould still be the Fungus Falls. Will meet back at Grudge Pit.\n\nOk, Tuktuk will try best.\n\nWill shoot poison again.\n\nSo much poison.\n\nEverywhere.", objectives = "Help Tuktuk face 3 difficult feelings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92630] = { id = 92630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pursuit Continues", description = "I bring word from Magister Umbric!\n\nHis apprentice, Leona, has been preoccupied with a desire to learn how the ways of the Illidari.\n\nShe apparently found another demon hunter willing to train her, should she prove herself worthy. But after what happened the last time she sought such a mentor, Umbric is concerned for her safety.\n\nUmbric requests you join Leona for this trial. Make sure she is not getting involved in something she is not prepared to handle.", completion = "Allari seeks to test my resolve. Nothing will deter me from this pursuit.", objectives = "Find Leona and Allari in K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92631] = { id = 92631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abhorrent Gauntlet", description = "Leona must demonstrate mastery of her weapons--and of her own enmity--by retrieving undamaged pieces of her kills.\n\nI will observe from here.\n\nYou, {name}, will go with her.", progress = "A demon hunter wields their ire, but is never ruled by it.", completion = "These parts are pristine. Well done, both of you.", objectives = "Harvest 24 undamaged parts from aberrations in the Tempest Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92632] = { id = 92632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of Wrath", description = "Cutting through scores of lesser foes is a simple task for any demon hunter. It's when we face a large, singular threat that our skills are truly tested.\n\nThat will be Leona's trial. You will act as her second.\n\nLet us see how she vanquishes a particularly dangerous opponent.", completion = "The same fire I see in Leona is what brought me where I am today.\n\nShe fights well. But more importantly, she has shown me the potential that the void elves possess.", objectives = "Kill Vraxik, the Dimensional Wanderer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92641] = { id = 92641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodying the Plain" }
quests[92647] = { id = 92647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shadowed Journey Through Time", description = "Champion! The curiosities hidden within the Shadowlands are numerous, as are the dangers. I could use some assistance clearing a path, so to speak.\n\nThere is much wealth to be gained should you choose to seek it.", completion = "Another prosperous arrangement. You have my thanks.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92649] = { id = 92649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shadowed Path Through Time", description = "Old enemies return and battle scars open once more.\n\nDefeat these foes and return with tales of glory.", progress = "I knew you would return victorious, champion.", completion = "What news from the war front?", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92650] = { id = 92650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flickering Anima", description = "The strange anima shimmers with a gentle hum, barely larger than a candle. As your hand draws near it erupts, flooding your mind with a torrent of visions. Triumphs earned through blood, regrets etched in grief, serene stillness all too fleeting, the bitter taste of betrayal. The unbearable cascade threatens to shatter your mind like glass. \n\nThen, silence. The visions end leaving an image Oribos seared into your mind.", completion = "<Ta'steld takes the curious anima, studying the wisp as it dances in his hand.>\n\nYou were right to bring this to me. As a purveyor of lost curiosities, I know just what to do with this. My thanks, Champion.", objectives = "Bring the Flickering Anima to Ta'steld in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92657] = { id = 92657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brewing Storm", description = "Our foothold in Stormarion is tenuous at best. We're barely holding the enemy off on one front. We certainly don't have the forces to assault the rest of the citadel.\n\nThat's where you and I come in. Meet me in Stormarion Citadel when you're ready to get to work.", completion = "Ready to get to work?", objectives = "Meet Lysikas in the Stormarion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92658] = { id = 92658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Acquisition", description = "All our forces are focused on this courtyard, but I think we've got another problem. I've scouted between assaults: there's activity in the lower keep. Not to worry you, but there are signs of another singularity.\n\nUp for a little reconnaissance? We'll go through the trench. They've got an impressive operation for gathering Void energy. Might as well hit that on the way. After all, our defenses here can't power themselves.\n\nIf I'm wrong, we can tell Maella we were proactively shoring up supply lines.", completion = "Good! The less Void energy the domanaar have to throw at us the better. I'll make sure this gets back to the assault. It'll help keep the defenses running.", objectives = "Steal Void Energy Reserves from the trench near Stormarion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92659] = { id = 92659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resource Denial", description = "I've got a hunch I need to follow in the lower keep, and that means going through the trench. I hate to miss targets of opportunity, and the Host's energy collecting operation is right there.\n\nHow do you feel about wrecking their production capacity? The longer it takes them to recover, the easier it'll be to maintain the offensive up here.\n\nIt's not complicated. If it looks useful to the enemy, smash it. After that, we'll move onto the main objective in the keep itself.", completion = "It should take them some time to get back to capacity. That'll keep the pressure off, at least for a while.", objectives = "Destroy 6 Void Condensers in the trench north of Stormarion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92660] = { id = 92660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Null Implements", description = "Yes, there may be another unstable singularity. No, I didn't tell anyone. We don't have enough forces to divert our attention--that's why I asked you to accompany me. Besides, we've only got the one Singularity Anchor.\n\nDon't worry though, I've got a plan. These domanaar are experts on shaping the Void, so they must have some means of controlling singularities. Get in there and grab any tools that look important.\n\nWe'll find a way to stabilize this singularity ourselves.", progress = "I'm sure a domanaar's tools will be able to stabilize a singularity.", completion = "Marvelous! Let's see what you've got.\n\n<Lysikas stares blankly at the tools you've acquired.>\n\nI have no idea how to use any of these.", objectives = "Collect domanaar tools in the Stormarion Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92661] = { id = 92661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer Meet Anvil", description = "I don't approve of Lysikas's disregard for duty, but I do trust his instincts. If he says there's something here we need to see, then he's probably right.\n\nEven if he's wrong, we shouldn't waste this opportunity. A domanaar weaponsmith and researcher does his work from here. With most of the Stormarion forces attacking our Singularity Anchor, he should be an easy target. Take him out.", completion = "Good work. He was dangerously adept at crafting void weaponry. The Devouring Host's blades will be a bit duller with him dead.\n\nUnfortunately, we have a much bigger problem.", objectives = "Slay Telumnus and 8 Stormarion Keep forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92662] = { id = 92662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core Collapse", description = "This singularity could reach critical mass at any moment. We've no time to evacuate. It will devour our forces in the upper citadel, maybe even the Ingress.\n\nWill you handle the tools? I've no idea how they work, but you've used more artifacts and seen more strange magic than most. Remember, the Void responds to will. Use the tools and command the singularity to stabilize. I trust you'll figure out the rest.\n\nThe Host will try to stop us. Lay down some defenses, then I'll cover you while you work.", completion = "That's one crisis averted, though this singularity's power was nothing compared to the one in the upper citadel. Our researchers are still working on a permanent solution, but at least we've only one cosmic disaster to focus on now.\n\nA shame the tools didn't survive. Our researchers could have used them to improve our Singularity Anchor.", objectives = "Avert the singularity collapse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92688] = { id = 92688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronze Simulacrum", description = "<Erus will be delighted to scrap this for you for a heaping sum of bronze.>", progress = "You have something for Erus?", completion = "YES! Erus will scrap!", objectives = "Give the Bronze Simulacrum to Erus at the Infinite Bazaar near Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92692] = { id = 92692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Test!", description = "All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador.\n\nThe Iron Horde seek to control Talador. The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance.\n\nForeman Eksos is currently establishing an outpost in Talador. Travel there and stop the Iron Horde.\n\nGlory to the Alliance!", objectives = "Speak with Foreman Eksos in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92694] = { id = 92694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dusk Among Pigments", description = "As Zur'ashar, our oath is to safeguard the harmony within the visions and the histories we preserve.\n\nYet Orn'shan's crude strokes are reckless. Their creative impulses lack refinement, disturbing the balance we are sworn to protect. In a misguided attempt at creativity, they've created uncontrollable chaos and are distorting the very truths they sought to record.\n\nPerhaps they will heed the words of an outsider before their reputation collapses entirely.", completion = "Are you here to ridicule me as well?", objectives = "Speak with Orn'shan in Amirdrassil Roots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92695] = { id = 92695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stroke of Storms", description = "I... I don't think I can mend this. The Zur'ashar were right. I am no true paintmaker. I cannot even capture history properly within my own memories... how could I ever hope to honor it in moments that matter?\n\nI thought I could create something beautiful... something worthy. I was foolish to try.\n\nCan you... can you help me clean this mess? I... I have no hope left to do it myself.", progress = "I fear I ruined everything.\n\nHave you been able to undo the destruction I brought upon this vision?", completion = "You actually did it? If an outsider can clean up my chaos, perhaps my work isn't a lost cause after all.", objectives = "Use the visionstone to enter the painting and restore harmony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92696] = { id = 92696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colors Born Anew", description = "Outsider... thank you. I'm still shaken... but I can feel a small spark returning. I'd nearly abandoned my work entirely, yet your kindness... it has steadied me.\n\nI think I finally see what I'm meant to create: something meaningful that honors the Zur'ashar tradition through my voice, but to begin, I need the raw essence of color itself.\n\nWill you help me collect the ingredients I need? I'd be looking for anything I can use to turn into paint.", progress = "Have you collected the ingredients I need?", completion = "Every pigment, every scrap of inspiration, will bring this idea to life, and I couldn't do it without you.", objectives = "Collect ingredients for Orn'shan from the Shrouded Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92697] = { id = 92697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hues of Tomorrow", description = "I... never expected to feel this again. Your help has given me hope. These ingredients feel right, and maybe even enough.\n\nI want you to be the first to paint. Do not fret over perfection. Paint what you feel, and I'll capture its essence into the memory I preserve.\n\nI look forward to see what you create.", progress = "Have you put paint to stone and watched your creativity flow?", completion = "You've reminded me that creation isn't just about skill: it's about daring to try, imagination, and expression. Even though my work differs from the other Zur'ashar painters, it still has worth.\n\nI need to learn to believe in myself again, and to slowly hone my craft.\n\nThank you.. for helping me see possibility where I only saw failure.\n\nI am eager, yet cautious, to begin my next piece. Perhaps this time, it will be something worthy of the name I carry.", objectives = "Paint Pictures for Orn'Shan in Amirdrassil Roots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92713] = { id = 92713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes Rekindled", description = "The relics you restored still hum with the visions you once walked.\n\nTheir stories yearn to be lived again, and each retelling leaves the world just a little richer than before.\n\nReturn them to the shrines, let the memories flow, and I shall place in your hands a reward for one who walks the paths of legend.", objectives = "Select a relic to experience once again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92715] = { id = 92715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Invitation Only?", description = "Fancy yourself a Brawl'gar contender do you, {class}? They don't let just anyone in there, you know. Certainly not without an invitation.\n\nThat said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.", completion = "Looking for a Brawler's Guild invitation are you?\n\nVery hard to come by those, or expensive, or both!\n\nBut maybe you and I can work out a deal.", objectives = "Talk to Alton Philips near the Brawl'gar Arena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92728] = { id = 92728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dogged Disturbances", description = "That dog! It ran through here and disrupted every lesson on the schedule. Now there are fire elementals everywhere and my students are ill-prepared to handle this mess. How am I supposed to teach in all of this chaos?\n\nYou look capable--would you clear out some of these rowdy little elementals? The sooner we get this situation under control, the better!", progress = "Have you gotten those rowdy little sparks under control?", completion = "Thank you for your assistance! My students should be able to handle the rest of them after a few quick lessons. We'll just call this a learning opportunity.", objectives = "Kill 8 Rowdy Elementals in Thalassian University.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92729] = { id = 92729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hounded and Hassled", description = "Gilneas and Kul Tiras are both known for their hunting hounds. With the resurgence of elfhounds in Silvermoon, I thought perhaps they could be similarly utilized. They're dogs, after all. How hard could training possibly be?\n\nLong story short, that dog made a mess and dashed off. I have to clean this up. \n\nWould you please find that creature and bring him back to me before the local canine cafe has my head? I only borrowed him for the day!", completion = "A dog? Yes I've seen a dog--look at this place! Just look at what he's done!", objectives = "Speak to Magistrix Zaedana in Thalassian University.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92732] = { id = 92732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Disturbance", description = "We have had victories against the Lightbloom, but Alndust is rare. Until we can gather more, the Lightbloom continues its spread. Our forces are stretched too thin to watch their every movement.\n\nA scout spotted a strange corpse by the road to the east, along with a report of a general disturbance of the light-cursed creatures. I can't look into both at once. Could you find that corpse while I investigate deeper into the Encroaching Bloom?", completion = "<This corpse appears to be covered with Lightbloom spores and was fighting recently. It must be what the scout saw.>", objectives = "Go to the disturbance Hannan's scout found.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92736] = { id = 92736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Stroll", description = "<These potatoad creatures are seldom seen near the Lightbloom. It is covered in spores and looks like it was trying to escape. You should search for more clues.>", completion = "This herd was seized recently--the signs you discovered make that clear. This encroachment is pressing into untainted lands, and the herds could be depleted beyond recovery.\n\nI appreciate your help, but there is more that must be done.", objectives = "Search for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92737] = { id = 92737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Carnage", description = "The Lightbloom has infected many of these potatoads and spurred them into a frenzy. They spread the spores and reproduce at a dangerous rate.\n\nIf we don't act, we will be overrun. Will you cull this heard while I search for the source of the corruption?", progress = "We must protect Harandar's natural species from this invasive growth.", completion = "It is a shame to destroy the creatures of Harandar, but sometimes it must be done to protect the land.", objectives = "Kill 12 Lightfrenzied Potatoads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92738] = { id = 92738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potatoad Tots", description = "It is too late for the adults, but the young may still be saved. If you can capture them, we can remove the spores before they take root.\n\nGather up the spore covered potadpoles and bring them to me. I will take them to Har'alnor myself to purge this Lightbloom.\n\nDo not let their first breaths be their last. Please, {name}: save the babies.", completion = "You have saved so many. The balance of the land may still stand thanks to your efforts.", objectives = "Collect 8 Lightspored Potadpoles and bring them to Hannan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92739] = { id = 92739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O.K. Bloomer", description = "I have discovered the lair of a cunning creature I call Adzikel. With luck, this name will soon be forgotten. \n\nAdzikel sneaks into the potatoad nests to steal their young, and plants the Lightbloom spores to accelerate their growth into the frenzied toads, which spread more spores.\n\nFor the little ones to have a chance, I must return to Har'alnor, but you have earned the right to slay this beast. Go with honor, and finish the hunt!", completion = "The Lightbloom is persistent, but so are you. Aln'hara's lands and creatures remain thanks to your efforts.\n\nThe young are being restored to their natural habitat, freed of the spores--all of them except this one. It is too small for the wild.\n\nIt will need a caregiver, and I think it has bonded to you.", objectives = "Kill the creature spreading these spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92740] = { id = 92740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questionable Qualifications", description = "Well {class}, it's your lucky day. I just happen to have an extremely genuine Brawler's Guild Invitation right here in my stockpile.\n\nThat said I'll need a moment to process the paperwork. That requires my complete concentration without your prying eyes on me. So do please give me a moment.", progress = "Here's your extremely genuine Brawler's Guild Invitation.\n\nPlease note all sales are final.\n\nThere will be no refunds, or receipts.", completion = "Some of the lines look a little crooked.", objectives = "Purchase an extremely genuine Brawler's Guild Invitation from Alton Philips.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92746] = { id = 92746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twist of the Stormfields", objectives = "Craft a blade with Decimus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
