quests[92809] = { id = 92809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level 60" }
quests[92816] = { id = 92816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter for Adventure", description = "<You look down to see a rough looking letter with your name on it.\n\nWhy not open it up to see what's inside?>", objectives = "Open the Adventuring Letter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92845] = { id = 92845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Invitation Only?", description = "Fancy yourself a Brawlpub contender do you, {class}? They don't let just anyone in there, you know. Certainly not without an invitation.\n\nThat said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.", completion = "Looking for a Brawler's Guild invitation are you?\n\nVery hard to come by those, or expensive, or both!\n\nBut maybe you and I can work out a deal.", objectives = "Talk to Pick Butterworth near Bizmo's Brawlpub in the Deeprun Tram.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92848] = { id = 92848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: The Grand Magister's Drink" }
quests[92851] = { id = 92851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questionable Qualifications", description = "Well {class}, it's your lucky day. I just happen to have an extremely genuine Brawler's Guild Invitation right here in my stockpile.\n\nThat said I'll need a moment to process the paperwork. That requires my complete concentration without your prying eyes on me. So do please give me a moment.", progress = "Here's your extremely genuine Brawler's Guild Invitation.\n\nPlease note all sales are final.\n\nThere will be no refunds, or receipts.", completion = "Some of the lines look a little crooked.", objectives = "Purchase an extremely genuine Brawler's Guild Invitation from Pick Butterworth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92855] = { id = 92855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Haste, Not Waste", objectives = "What, you think I'm just going to give you my crafts for free?\n\n<Lidamorrutu grumbles.>\n\nI suppose that's exactly what I'm going to do. Eternus's orders, something about speeding up the experiment.\n\nJust don't lose it or, worse, let Erus anywhere near it.You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92857] = { id = 92857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ta'readon's Mount Voucher", description = "This token bears the seal of Overseer Ta'readon in Oribos. They would be interested in seeing this.", completion = "I see you have served our merchants admirably. Accept one of our finest steeds as a reward.", objectives = "Bring Ta'readon's Mount Voucher to Overseer Ta'readon in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92864] = { id = 92864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drift Them Away", description = "With the hydras hunted out of the area, the drifter population in the cascades to the west is on the rise. Egg sacks are making the water murky and undrinkable, and the drifters are becoming very territorial.\n\nWe must ensure that the reintroduction of the hydras will succeed. We need to cull the number of drifters and clear some of their egg sacks.\n\nYou look like someone capable of doing this task. Will you help me?", completion = "It pains me to cull the drifter population. However, if left unchecked, their numbers would have led to the collapse of the ecosystem.", objectives = "Slay 8 Cascade Drifters and remove 5 Drifter Egg Sacks from the cascades at Nordrassil Roots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92865] = { id = 92865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Buds", description = "The orchid hydra's favorite food is the violet chloroceros--especially the buds on the bull's back.\n\nWith the hydras gone for so long, the violet chloroceros grazed too much of the fauna. Soon, there will only be mud in that once lush and beautiful part of Harandar.\n\nI want to introduce my hydras to their primary source of food, and I would appreciate it if you could bring me four of those buds.", progress = "The precious budlings will be very happy with their first taste of the chloroceros buds.", completion = "The budlings seem to be satiated for now. I am comfortable moving to the second phase of reintroducing them to their natural habitat.", objectives = "Collect 4 Chloroceros Buds from the Violet Chloroceros, then feed them to the Hydra Budlings in Har'athir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92866] = { id = 92866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Hydra-ted", description = "With the previous tasks done, it is time to reintroduce the budlings to the wilds.\n\nI have marked suitable locations to place the budlings. The little hydras will be an easy pick, so expect predators to attack you.\n\nI am sad to see them go. However, I know it is for the ecosystem's and their own good.", completion = "You are back, and the feeling is bittersweet. On one hand, I have lost my babies, but on the other, I know it is for the best. I could go and visit them... or maybe I shouldn't, considering they would be unruly and four times my size.\n\nRegardless, thank you for your help. I will never forget this kindness.", objectives = "Place the budlings in the marked areas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92868] = { id = 92868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Went Thataway", description = "You've been invaluable, {name}. As for that little menace, after he was done wreaking havoc here, I didn't really pay attention to where he went next. I'm sure you'll find him eventually. \n\nLet's hope you do before he wrecks half the city, hmm?", completion = "A dog? Yes I've seen a dog, just look at what that monster's done to the pond!", objectives = "Speak to Drathen in the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92869] = { id = 92869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishy Dis-pondencies", description = "That dog tore right through the pond and sent half the sunwhiskers flying right out of the water! Quickly, get them back in the pond before they perish!", progress = "Hurry! They're terribly delicate creatures!", completion = "Your methods were... interesting, but I cannot deny the results. The sunwhiskers may be a little shaken up, but they'll recover soon enough now that they're back in the water where they belong. My thanks.", objectives = "Return 8 Coy Sunwhisker to the pond in the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92870] = { id = 92870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scoot Along Now", description = "That dog! The last I saw he was tearing through the pond. I didn't see where he went, but he has to be nearby!\n\nHis barks... they haunt me...", completion = "Lil' Scoots! Welcome back, you fuzzy menace. Thank you, champion. I'll return him to the cafe posthaste.\n\nAs for training... I think I shall stick to the local lynx. Far better manners.", objectives = "Catch Lil' Scoots and return him to Ranger Telenus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92875] = { id = 92875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the War Within", description = "I fear your time in Valdrakken must come to an end.\n\nDark forces gather to threaten other parts of Azeroth. We will do what we can to uncover Iridikron's schemes.\n\nYou must learn more of what has unfolded.", completion = "<The tome floats in front of you. Its pages are filled with knowledge of all that has happened.>", objectives = "Consult the Tome of History within Valdrakken to learn about the War Within saga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92882] = { id = 92882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Plight", description = "I am desperate enough to ask an outsider for help.\n\nTo join the Ka'dani, the elite hunters of Har'athir, you must complete a ritual under the guidance of an experienced Ka'dani. However, there are none left to guide me, so I cannot take the trial.\n\nBut I have heard words of your actions. Maybe Akazi, the Ka'dani Elder, would let you stand as my guide. You may not know the ritual, but you know the hunt.\n\nPlease, let us speak to Elder Akazi. We must try.", progress = "Ketan tells me that you wish to mentor him. Is this true?", completion = "I will give you my blessing, {name}. Although you are not a Ka'dani, tales of your prowess precede you. Your skills in the hunt need no introduction.\n\nI know that you will be able to give Ketan the guidance he needs.\n\nYou will both take part in the Ka'dani trials: you as an honorary Ka'dani, and Ketan as your trainee.", objectives = "Ketan wants you to talk to Elder Akazi about the Ka'dani trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92883] = { id = 92883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Duty", description = "At the start of the trial, the mentor and trainee gather materials to forge a hunting weapon.\n\nThe weapon is more than an extension of the Ka'dani-- it's part of their being. There is no other weapon like it, as each is unique.\n\nYou will help Ketan hunt and gather the materials and decorations, as well as a gift for the weaponsmith.", progress = "Were you able to get everything? I know some of the required materials can be hard to gather.", completion = "These look pristine.\n\nThank you for doing this for me. Maybe one day I will be able to do the same for someone else.", objectives = "Hunt down beasts around Har'athir and collect materials to forge a Ka'dani weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92884] = { id = 92884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Weapon", description = "Forging the Ka'dani weapon is a crucial moment in the trial. We will have to follow Al'yaat's instructions.\n\nOnce Al'yaat forges the weapon, you will bring it to Elder Akazi.\n\nThere will be a short ceremony where he will hand me the weapon. The ceremony concludes with the elder announcing our final task.\n\nI shouldn't let the excitement take the better of me, but one thing at a time. We must be patient and calculated as if we were on a hunt.", progress = "Forging a Ka'dani weapon is not an easy feat. A master craftsman must use the very best materials brought by the mentor and trainee.", completion = "<Elder Akazi inspects the Ka'dani spear and nods.>\n\n{name}, you have proven to be a worthy mentor. Ketan deserves this weapon as much as it deserves Ketan.\n\nThe two of you have one more task before this journey comes to an end.", objectives = "Help Al'yaat forge the Ka'dani weapon, then deliver it to Elder Akazi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92885] = { id = 92885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Prey", description = "The last trial stands before you. Together, you have forged a weapon that will fell any beast, but the weapon is nothing without the hunter.\n\nSince you are not a Ka'dani, I present you with a difficult hunt. Ketan and you will hunt down and slay a prey known to all Har'athir hunters: the great Radooni. The beast ventured too close to Har'athir and should be a suitable hunt.\n\nReturn to me once your hunt is complete and Radooni's sap is on the spear.", completion = "I see now that your presence here and Ketan's perseverance were set by the goddess herself. I am impressed by your actions and resolve. Thanks to you, Ketan's path is clear.", objectives = "Hunt down the great Radooni, then return to Elder Akazi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92890] = { id = 92890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Voidlight Marl", objectives = "Thank you for your assistance. Please accept these as thanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92891] = { id = 92891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cluster of Voidlight Marl" }
quests[92892] = { id = 92892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trove of Voidlight Marl" }
quests[92926] = { id = 92926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Astalor's Initiative", description = "Ah, {name}. I am glad to see you here in our city, even if the times are trying.\n\nWe are once again beset on all sides by uncertain friends and dangerous foes, but I am not unprepared. I have a... guest, housed nearby. They may hold the key to our city's survival. \n\nMeet me near the harbor if you have the strength to do what must be done.", completion = "I see your interest has been piqued. \n\nExcellent.", objectives = "Meet Astalor Bloodsworn near the harbor in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92939] = { id = 92939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not Just a Rock!", progress = "Why are these beasts even eating these rocks?", completion = "Yes, you found more rubble!\n\nHave you noticed the runes carved on these rocks emanate Void? Creatures of Voidstorm seem to have an endless hunger for that magic.\n\nSo, I think these beasts are eating the Void in these runes. At least, that makes the most sense.", objectives = "Collect 6 Ancient Rubble from monsters in the Storm Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92944] = { id = 92944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sifting Through Void", description = "There's no rubble on the surface. The beasts are burrowing, so they must be finding it in a cavern underground.\n\nI've been thinking of how to get there.\n\nYou've noticed the vortexes that dot the Storm Fields? They twist space, moving things from place to place.\n\nStep through one and I can reveal the anomalous residue that surrounds them.\n\nCollect the residue and I can make a spell to redirect the portal to where the source of the rubble is!", progress = "I had some suspicion about these runes not being domanaar or ethereal. The specter all but confirms my thoughts. This could be something different. Maybe even a civilization!", completion = "Did you hear that? This world was called Predacea!\n\nWhat a revelation!", objectives = "Jump in the Stellar Vortexes in the Storm Fields and collect 10 Anomalous Residue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92945] = { id = 92945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Anguish", description = "These threats we chase are intelligent. Determined. Deadly.\n\nTheir ingenuity will seek to confound you. Their strength will seek to destroy you. It is from their very will to live--to predate--that we will extract the essence required to fuel the magical defenses of our city. \n\nI have had my assistants lay out our friend's toys. You'd do best to familiarize yourself with them.", progress = "Speak with Astalor Bloodsworn to continue.", completion = "One fool's trap is another elf's treasure.", objectives = "Learn how to hunt your prey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92946] = { id = 92946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried in the Dark", progress = "What more could we learn?", completion = "If this specter and his tablets are to be believed, this world was once thriving with multiple civilizations.\n\nJust like on Azeroth, they fought endless wars. They asked Akintunde for a weapon to end all wars, and he delivered... by making one that ended everything.", objectives = "Jump into the northernmost Stellar Vortex in the Storm Fields and investigate the cave beyond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92948] = { id = 92948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Over My Head", progress = "I sensed no remorse at all from him. How could that be?", completion = "Forgive me, {name}. That all happened so quickly.\n\nWas any of it even true? But what else could that spirit have been?\n\nAn entire world... civilizations that used to thrive right where we stand? Could that really be?\n\nI can tell you only one thing for certain. \n\nThis will haunt me for the rest of my days.", objectives = "Step into the Northernmost Stellar Vortex in the Stormfields to confront Akitunde the Unstoppable.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92961] = { id = 92961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSentinel of stone.\nFirst to greet each new neighbor.\nSeek out the deep shade.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92962] = { id = 92962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nClouds bow to the stone.\nHeights where gryphons dare not fly.\nAbove all, it waits.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92963] = { id = 92963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nHighland rime meets mists.\nGateway to the dusky wood.\nThe dead point the way.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92964] = { id = 92964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nMountain guardian.\nDark forest whispers below.\nLook to the lone pine.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92965] = { id = 92965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nNo leaves, yet it blooms.\nStill limbs cradle gentle glows.\nWade where violet grows.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92966] = { id = 92966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nFireflies glow and flit.\nFalls feed the whispering wood.\nThe drowned cave awaits.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92967] = { id = 92967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nNames worn down by time.\nStone weeps where the water sings.\nDrop a coin, then dig.\n\nGood luck!", progress = "You found the treasure!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92968] = { id = 92968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nTrellis frames the Torch.\nA seat above misty shores.\nSeek the ledge below.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92969] = { id = 92969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nTribute to the lost.\nWhere seaspray climbs ancient cliffs.\nA lonely bell tolls.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92970] = { id = 92970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSmall farmer's homestead.\nWhere cows bask in golden light.\nDig between the rows.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92971] = { id = 92971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nCows low in their pen.\nLeaves fall on the roundabout.\nTreasure waits within.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92972] = { id = 92972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nBelow autumn soil.\nGargled seaweed and dead fish.\nStone mouth drinks the sea.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92973] = { id = 92973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nWater flows below.\nWhile fresh cider flows above.\nDig where the wheel churns.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92974] = { id = 92974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nAboveground tunnel.\nLights mark where life's blood once flowed.\nLook atop the falls.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
